INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('ddccb1fb-d4de-4539-8cfd-277a101a5ff0', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'B1 Preliminary', 'b1-preliminary', 1, 7, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/B1.webp', 'Il corso B1 Preliminary si rivolge a chi ha una conoscenza intermedia dell''inglese e vuole acquisire competenze pratiche per la vita di tutti i giorni. Il programma si concentra sull''uso della lingua in situazioni reali, come la comprensione di testi semplici, la scrittura di email e la partecipazione a conversazioni su argomenti familiari. L''obiettivo è preparare gli apprendenti all''esame B1, una certificazione che attesta un livello di autonomia nell''uso della lingua.', 'e1180b01-1111-4000-8000-000000000001', 1, 1, ARRAY[1,3], '18:00', '19:15', 75, 2, NULL, NULL, 3, 122, 122, NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('f2833ac6-27d4-47a5-a193-a5891fd3590f', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'Kids (6-7 anni)', 'kids-6-7-anni', 1, 2, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/Kids.webp', 'Le basi dell''inglese attraverso il gioco, la creatività e la comunicazione.
INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('1af53930-1aaf-4a29-bc04-6c82fe698dbb', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'Beginners / Starters (8-10 anni)', 'beginners-starters-8-10-anni', 1, 3, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/Begginers.webp', 'Il corso Starters si rivolge a chi inizia a studiare inglese, rendendo l''esperienza divertente. Sviluppa le quattro abilità linguistiche di base (ascolto, conversazione, lettura, scrittura) con attività giocose e un linguaggio semplice. Prepara per il primo esame ufficiale Cambridge.', 'e1180b01-1111-4000-8000-000000000001', 1, 1, ARRAY[1,3], '17:00', '18:00', 60, 2, NULL, NULL, 3, 97.6, 97.6, NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('c2f00f39-0963-4e31-b786-844296c6c94a', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'B2 First', 'b2-first', 1, 8, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/B2.webp', 'Il corso B2 First è pensato per chi ha un livello intermedio-superiore e desidera un uso più fluente e articolato dell''inglese. Il programma approfondisce le abilità linguistiche per comprendere testi complessi, partecipare a discussioni su argomenti astratti e scrivere testi dettagliati. Questo corso prepara all''esame B2 First, un certificato ampiamente riconosciuto che attesta la capacità di lavorare o studiare in un contesto anglofono.', 'e1180b01-1111-4000-8000-000000000001', 1, 1, ARRAY[2,4], '18:00', '19:15', 75, 2, NULL, NULL, 3, 146.4, 146.4, NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('7b051ab1-11c3-4714-b78a-c532b5b084be', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'Movers', 'movers', 1, 4, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/Movers.webp', 'Il corso Movers è per chi ha già le basi dell''inglese. Consolida le quattro abilità con vocabolario più ampio e strutture grammaticali più complesse. Prepara per l''esame Cambridge di livello intermedio, un passo fondamentale verso la certificazione Flyers.', 'e1180b01-1111-4000-8000-000000000001', 1, 1, ARRAY[1,3], '18:15', '19:30', 75, 2, NULL, NULL, 3, 109.8, 109.8, NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('94aea8d0-5f00-46ba-afe5-9cc410419082', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'Flyers', 'flyers', 1, 5, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/Flyers.webp', 'Il corso Flyers è per chi ha una conoscenza consolidata dell''inglese. Il programma rafforza le quattro abilità linguistiche con l''uso di frasi più complesse e un vocabolario più ricco, preparandoli a comunicare in situazioni di uso comune. Il corso è un passo importante verso i livelli successivi, come A2 Key for Schools.', 'e1180b01-1111-4000-8000-000000000001', 1, 1, ARRAY[2,4], '18:15', '19:30', 75, 2, NULL, NULL, 3, 109.8, 109.8, NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('166f8ce9-4011-459e-9263-803205155d37', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'C2 Advanced', 'c2-advanced', 1, 10, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/C2_Advanced.webp', 'Il corso C2 Proficiency è rivolto a studenti che desiderano raggiungere un livello di inglese paragonabile a quello di un madrelingua. Attraverso un percorso avanzato e altamente specializzato, gli studenti perfezionano ogni aspetto della comunicazione, acquisendo sicurezza nell''utilizzo della lingua in contesti accademici, professionali e internazionali.
INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('9717a2a6-4717-496c-abac-43df51d42580', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'A2 Key for Schools', 'a2-key-for-schools', 1, 6, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/A2.webp', 'Il corso A2 Key è rivolto a chi ha una conoscenza di base dell''inglese e desidera ottenere la prima certificazione Cambridge. Il programma mira a sviluppare la capacità di comunicare in situazioni quotidiane, sia scritte che orali, usando un linguaggio semplice e chiaro. Il corso è un passo cruciale per gli apprendenti che vogliono ottenere una certificazione ufficiale e passare ai livelli successivi, come il B1 Preliminary.', 'e1180b01-1111-4000-8000-000000000001', 1, 1, ARRAY[2,4], '16:00', '17:15', 75, 2, NULL, NULL, 3, 109.8, 109.8, NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses ("id", "created_at", "updated_at", "name", "slug", "status", "sort_order", "photo_url", "description", "teacher_id", "course_format", "schedule_type", "schedule_days", "start_time", "end_time", "lesson_duration_minutes", "lessons_per_week", "total_lessons", "total_hours", "billing_type", "price", "subscription_price", "stripe_monthly_price_id", "category") VALUES ('4b162176-b571-454b-bdb6-556d3b921800', '2026-09-17T15:52:21.054028+00:00', '2026-09-17T15:52:21.054028+00:00', 'Toddlers (3-5 anni)', 'toddlers-3-5-anni', 1, 1, 'https://hcxpfzsmzusolvhtuhhm.supabase.co/storage/v1/object/public/courses_images/Toddlers.webp', 'Il primo incontro con l''inglese in un ambiente divertente e stimolante.
